for (const item of items) {
    // 1. Verificar si el campo Referencia existe y es una cadena de texto.
    if (item.json.Referencia && typeof item.json.Referencia === 'string') {

        // --- LIMPIEZA INICIAL (MANTENIDA) ---
        // 2. Aplicar la sustitución: Reemplaza "F-" o "f-" solo al inicio (^) por un string vacío.
        item.json.Referencia = item.json.Referencia.replace(/^F-/i, '');

        // --- LIMPIEZA PARA MERGE BY ID (AÑADIDA) ---
        // 3. Estandarizar la clave de unión:
        //    a) Eliminar espacios al inicio y al final (trim()).
        //    b) Convertir todo a mayúsculas (toUpperCase()).
        let referenciaLimpia = String(item.json.Referencia).trim().toUpperCase();

        // 4. Sobreescribir la Referencia con el valor limpio y estandarizado
        item.json.Referencia = referenciaLimpia;
    }
    // Todas las demás columnas se mantienen porque estamos modificando el ítem en su lugar.
}

return items;

const finalFileName = "Ezaudita.xlsx"; // El nombre de archivo deseado.
const newStaticKey = "Ezaudita"; // La clave binaria estática para n8n.

return items.map(item => {
    // 1. Verificación: Aseguramos que solo haya un archivo binario, según lo esperado.
    if (!item.binary || Object.keys(item.binary).length !== 1) {
        // Si no hay 1 archivo (o no hay binarios), devolvemos el ítem sin cambios.
        return item; 
    }

    // Obtenemos la clave binaria dinámica original (ej. 'data_0', 'attachment_1')
    const originalDynamicKey = Object.keys(item.binary)[0];

    // Guardamos la referencia al objeto binario.
    const originalBinary = item.binary[originalDynamicKey];

    // 2. ELIMINAMOS la clave dinámica de entrada.
    delete item.binary[originalDynamicKey];

    // 3. Creamos la nueva clave ESTÁTICA ('Ezaudita').
    item.binary[newStaticKey] = originalBinary;

    // 4. SOBRESCRIBIMOS la metadata interna del nombre de archivo.
    // Esto es lo que verán los nodos que manejan el archivo, como un nodo de Guardar en Google Drive/SFTP.
    item.binary[newStaticKey].fileName = finalFileName;

    return item;
});

// La función principal debe ser 'return' o un 'async' si usa Promesas.
return items.map(item => {
    // 1. Obtener la data binaria del ítem actual.
    // 'binary' es donde n8n almacena los archivos adjuntos.
    const binaryData = item.binary;

    // 2. Crear un nuevo objeto para almacenar solo los adjuntos de Excel.
    const newBinaryData = {};

    // 3. Iterar sobre todos los archivos binarios adjuntos en este ítem.
    if (binaryData) {
        for (const attachmentName in binaryData) {
            // Obtener el objeto del adjunto (que contiene 'fileName', 'mimeType', etc.)
            const attachment = binaryData[attachmentName];

            // 4. Verificar la extensión del archivo.
            // Convertimos a minúsculas para una comprobación insensible a mayúsculas/minúsculas.
            const fileNameLower = attachment.fileName ? attachment.fileName.toLowerCase() : '';

            // 5. Si es un archivo Excel (xlsx o xls), lo conservamos.
            if (fileNameLower.endsWith('.xlsx') || fileNameLower.endsWith('.xls')) {
                // Se agrega el adjunto al nuevo objeto binario.
                newBinaryData[attachmentName] = attachment;
            }
        }
    }

    // 6. Devolver el ítem original, pero con el objeto binario filtrado.
    // Esto sobrescribe el objeto 'binary' con solo los archivos Excel.
    return {
        ...item, // Conserva los campos de datos JSON (e.g., el cuerpo del correo).
        binary: newBinaryData
    };
});

const map = {
  "LMM Centro": "LMM", "GDL Del Fresno": "GDL", "MTY Valles": "MTY01",
  "CLN Los Pinos": "CUL", "HMO Balderrama": "HMO", "Chihuahua Zapata": "CUU",
  "QRO - Carrizal": "QRO01", "Tijuana-Aquino": "TIJ", "Sucursal Web": "WCE",
  "MTY - Joyas": "MTY02"
};

// Accedemos directo a tu lista de datos (que viene agrupada en el primer item)
const filas = items[0].json; 

return filas
  // 1. Filtramos para quitar los metadatos técnicos (fieldCount, etc.)
  .filter(fila => !fila.fieldCount)
  // 2. Mapeamos valores y renombramos la columna
  .map(fila => {
    const nombreCorregido = map[fila.Sucursal] || fila.Sucursal;

    // Creamos el objeto final sin la columna vieja 'Sucursal'
    const { Sucursal, ...restoDeDatos } = fila; 

    return {
      json: {
        ...restoDeDatos,
        Nombre_Sucursal: nombreCorregido
      }
    };
  });

// 0. Recuperar información del nodo de fecha
const fechaInfo = $node["Definir fechas1"].json;
const tituloGeneral = `Cotejo ${fechaInfo.nombre_mes} de ${fechaInfo.año_completo}`;

// Helper para formatear cuenta: 40100100011 -> 401-001-0001-1
const fmtAcc = (acc) => {
  if (typeof acc !== 'string') acc = String(acc);
  if (acc.length < 11) return acc;
  return `${acc.slice(0,3)}-${acc.slice(3,6)}-${acc.slice(6,10)}-${acc.slice(10)}`;
};

// Helper para moneda (MXN)
const fmt = (num) => new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN' }).format(num || 0);

// --- SECCIÓN PROTEGIDA: LÓGICA DE COTEJO (INCLUYE CUENTA 402) ---
const cuentasVentas = ['40100100011', '40100100021', '40100100031', '40200100011'];
const cuentaEmbalaje = '40100100014';

const ordenSucursales = {
  "LMM": 1, "GDL": 2, "MTY01": 3, "CUL": 4, "HMO": 5, 
  "CUU": 6, "QRO01": 7, "TIJ": 8, "WCE": 9, "MTY02": 10
};

const conciliacion = {};
const sucursalesVistas = new Set();
const catalogoCuentas = {}; 
const saldosPorCuentaYSucursal = {}; 
const datosPktone = {};

Object.keys(ordenSucursales).forEach(suc => {
  datosPktone[suc] = { ventas: 0, notas: 0, embalaje: 0 };
});

for (const item of items) {
  const data = item.json;
  const sucursal = data.Nombre_Sucursal;
  if (!sucursal || !ordenSucursales[sucursal]) continue;

  const cod = data.Codigo_Cuenta_Completo;
  if (cod) {
    if (!catalogoCuentas[cod]) catalogoCuentas[cod] = data.Nombre_Cuenta;
    if (!saldosPorCuentaYSucursal[cod]) saldosPorCuentaYSucursal[cod] = {};
    saldosPorCuentaYSucursal[cod][sucursal] = (saldosPorCuentaYSucursal[cod][sucursal] || 0) + parseFloat(data.Saldo_Mensual_Nov_2024 || 0);
  }

  if (!sucursalesVistas.has(sucursal)) {
    datosPktone[sucursal] = {
      ventas: parseFloat(data.Ventas || 0),
      notas: parseFloat(data.Nota_Credito || 0),
      embalaje: parseFloat(data.Embalaje || 0)
    };
    sucursalesVistas.add(sucursal);
  }

  if (!conciliacion[sucursal]) {
    conciliacion[sucursal] = {
      Nombre_Sucursal: sucursal,
      PKT_Ventas: parseFloat(data.Ventas || 0),
      PKT_Embalaje: parseFloat(data.Embalaje || 0),
      CONTPAQi_Ingresos_Acum: 0,
      CONTPAQi_Embalaje_Saldo: 0
    };
  }

  const saldo = parseFloat(data.Saldo_Mensual_Nov_2024 || 0);
  if (cuentasVentas.includes(cod)) {
    conciliacion[sucursal].CONTPAQi_Ingresos_Acum += saldo;
  }
  if (cod === cuentaEmbalaje) {
    conciliacion[sucursal].CONTPAQi_Embalaje_Saldo += saldo;
  }
}
// --- FIN DE SECCIÓN PROTEGIDA ---

const KEYS = [];
for (let i = 0; i <= 25; i++) KEYS.push(" ".repeat(i)); 

const createRow = () => {
  let obj = {};
  KEYS.forEach(k => obj[k] = "");
  return obj;
};

let finalOutput = [];
const listaSuc = Object.keys(ordenSucursales).sort((a,b) => ordenSucursales[a] - ordenSucursales[b]);

// --- FILA 1: TÍTULO PRINCIPAL ---
let rowMainTitle = createRow();
rowMainTitle[KEYS[0]] = tituloGeneral;
finalOutput.push({ json: rowMainTitle });

finalOutput.push({ json: createRow() }, { json: createRow() });

// --- TABLA 1: COTEJO ---
let rowHeader1 = createRow();
const labels1 = ["Sucursal", "PKT_Ventas", "CONTPAQi_Ventas", "Status_Doc", "PKT_Embalaje", "CONTPAQi_Embalaje", "Status_Emb"];
labels1.forEach((label, i) => { rowHeader1[KEYS[i]] = label; });
finalOutput.push({ json: rowHeader1 });

listaSuc.forEach(nombre => {
  const suc = conciliacion[nombre];
  if (!suc) return;
  const v_pkt = Math.round(suc.PKT_Ventas * 100) / 100;
  const v_cont = Math.round(suc.CONTPAQi_Ingresos_Acum * 100) / 100;
  const diff_v = v_cont - v_pkt;
  const e_pkt = Math.round(suc.PKT_Embalaje * 100) / 100;
  const e_cont = Math.round(suc.CONTPAQi_Embalaje_Saldo * 100) / 100;
  const diff_e = e_cont - e_pkt;

  let row = createRow();
  row[KEYS[0]] = suc.Nombre_Sucursal;
  row[KEYS[1]] = fmt(v_pkt);
  row[KEYS[2]] = fmt(v_cont);
  row[KEYS[3]] = Math.abs(diff_v) > 0.01 ? fmt(diff_v) : "0";
  row[KEYS[4]] = fmt(e_pkt);
  row[KEYS[5]] = fmt(e_cont);
  row[KEYS[6]] = Math.abs(diff_e) > 0.01 ? fmt(diff_e) : "0";
  finalOutput.push({ json: row });
});

finalOutput.push({ json: createRow() }, { json: createRow() });

// --- TABLA 2: CONTPAQ ---
let title2 = createRow();
title2[KEYS[0]] = "CONTPAQ";
finalOutput.push({ json: title2 });

let rowSucNames2 = createRow();
listaSuc.forEach((suc, i) => { rowSucNames2[KEYS[i + 1]] = suc; });
finalOutput.push({ json: rowSucNames2 });

let rowHeader2 = createRow();
rowHeader2[KEYS[0]] = "CUENTA";
// Se eliminó la asignación de "SALDO" a las columnas de sucursal
finalOutput.push({ json: rowHeader2 });

const totalesPorSucursal = {};
const cuentasUnicas = Object.keys(catalogoCuentas).sort();

cuentasUnicas.forEach(cod => {
  let row = createRow();
  row[KEYS[0]] = `${fmtAcc(cod)} ${catalogoCuentas[cod]}`;
  listaSuc.forEach((suc, i) => {
    const saldo = saldosPorCuentaYSucursal[cod][suc];
    if (saldo !== undefined) {
      row[KEYS[i + 1]] = fmt(saldo);
      totalesPorSucursal[suc] = (totalesPorSucursal[suc] || 0) + saldo;
    }
  });
  finalOutput.push({ json: row });
});

let rowTotal2 = createRow();
rowTotal2[KEYS[0]] = "TOTAL SUMA DE SALDOS";
listaSuc.forEach((suc, i) => { rowTotal2[KEYS[i + 1]] = fmt(totalesPorSucursal[suc]); });
finalOutput.push({ json: rowTotal2 });

finalOutput.push({ json: createRow() }, { json: createRow() });

// --- TABLA 3: PKTONE ---
let title3 = createRow();
title3[KEYS[0]] = "PKTONE";
finalOutput.push({ json: title3 });

let rowSucNames3 = createRow();
listaSuc.forEach((suc, i) => { rowSucNames3[KEYS[i + 1]] = suc; });
finalOutput.push({ json: rowSucNames3 });

const totalesPKT = {};
let concepts = [
  { label: "VENTAS", key: "ventas" },
  { label: "NOTAS_CRED", key: "notas" },
  { label: "EMBALAJE", key: "embalaje" }
];

concepts.forEach(c => {
  let row = createRow();
  row[KEYS[0]] = c.label;
  listaSuc.forEach((suc, i) => {
    const val = (datosPktone[suc] && datosPktone[suc][c.key]) ? datosPktone[suc][c.key] : 0;
    row[KEYS[i + 1]] = fmt(val);
    totalesPKT[suc] = (totalesPKT[suc] || 0) + val;
  });
  finalOutput.push({ json: row });
});

let rowTotal3 = createRow();
rowTotal3[KEYS[0]] = "TOTAL PKTONE";
listaSuc.forEach((suc, i) => { rowTotal3[KEYS[i + 1]] = fmt(totalesPKT[suc]); });
finalOutput.push({ json: rowTotal3 });

return finalOutput;

const columnsToRemove = [
    // Columnas que se deben eliminar del output de Ezaudita/SAT
    "Saldo de la factura",
    "CFDIs de pago relacionados",
    "RFC receptor",
    "Receptor",
    "Uso de CFDI",
    "Método de pago",
    "Forma de pago"
];

/**
 * Función que convierte un número de serie de fecha de Excel a un objeto Date de JavaScript.
 */
function excelSerialDateToJSDate(serial) {
    const days = serial - 25569; 
    const ms = days * 24 * 60 * 60 * 1000;
    const date = new Date(ms);
    return date.toISOString().slice(0, 10); 
}

return items.map(item => {
    if (!item.json || typeof item.json !== 'object') {
        return item;
    }

    const data = item.json;

    // --- 1. CONVERSIÓN DE FECHA ---
    const fechaExpedicion = data["Fecha expedición"];
    if (typeof fechaExpedicion === 'number' && fechaExpedicion > 1000) {
        data["Fecha expedición"] = excelSerialDateToJSDate(fechaExpedicion);
    }

    // --- 2. CREACIÓN Y LIMPIEZA DE CLAVE ÚNICA "Serie-Folio" ---
    const serie = String(data.Serie || '');
    const folio = String(data.Folio || '');

    let serieFolio = serie + folio;

    // ESTANDARIZACIÓN AÑADIDA: Eliminar espacios y convertir a mayúsculas
    serieFolio = serieFolio.trim().toUpperCase();

    // --- 3. FILTRADO INICIAL DE COLUMNAS ---
    for (const column of columnsToRemove) {
        delete data[column];
    }

    // --- 4. ELIMINACIÓN DE COLUMNAS ORIGINALES (Serie y Folio) ---
    delete data.Serie;
    delete data.Folio;

    // --- 5. REESTRUCTURACIÓN DEL ORDEN Y AÑADIDO DE LA CLAVE EN POSICIÓN 2 ---

    const newJson = {
        "Fecha expedición": data["Fecha expedición"], 
        "Serie-Folio": serieFolio, // 2. Posición (Clave Limpia)
        "Total": data.Total,
        "Subtotal": data.Subtotal,
        "Total descuento": data["Total descuento"],
        "Neto": data.Neto,
        "Traslado IVA": data["Traslado IVA"],
    };

    // Devolvemos el nuevo ítem JSON.
    return {
        json: newJson
    };
});

return items.map(item => {
    const data = item.json;

    // --- 1. CREAR y LIMPIAR la columna "Serie-Folio" ---
    const serie = String(data.Serie || '');
    const folio = String(data.Folio || '');

    // Concatenamos y aplicamos la limpieza para el Merge By ID:
    const serieFolio = (serie + folio).trim().toUpperCase();

    // --- 2. REESTRUCTURAR Y ORDENAR LAS COLUMNAS ---
    const newJson = {
        // 1. Posición: Campo de Fecha
        "Fecha Facturacion": data.Fecha,

        // 2. Posición: La clave de unión (Serie-Folio)
        "Serie-Folio": serieFolio,

        // 3. Posición en adelante: El resto de las columnas
        "Nombre Cliente": data.NombreCliente || data.Cliente, 
        "Flete": data.flete,
        "Subtotal Embalaje": data.subtotalembalaje,
        "Multiservicios": data.Multiservicios,

        // **********************************************
        // SOLUCIÓN A LA COLISIÓN: RENOMBRAMIENTO
        "IVA (PKT)": data.iva,
        "Total (PKT)": data.total
        // **********************************************
    };

    // 3. Devolver el nuevo ítem JSON con la estructura final.
    return {
        json: newJson
    };
});

// 1. MAPA DE ABONOS TOTALES (Normalizado)
const abonosPorFolio = {};
items.forEach(item => {
    const d = item.json;
    const folioRaw = (d['Serie-Folio'] || d.Referencia || '').toUpperCase();
    const folioNorm = folioRaw.replace(/\s+/g, '').trim(); 

    const abono = (d.Tipo_Movimiento === 'Abono' && Number(d.Importe_Local) > 0) ? Number(d.Importe_Local) : 0;
    if (!abonosPorFolio[folioNorm]) abonosPorFolio[folioNorm] = 0;
    abonosPorFolio[folioNorm] += abono;
});

// 2. TRANSFORMACIÓN INICIAL (Filtro LMM con Normalización)
const todosTransformados = items.map(item => {
    const data = item.json;
    const serieFolioOriginal = (data['Serie-Folio'] || data.Referencia || '').trim().toUpperCase();
    const serieFolioNorm = serieFolioOriginal.replace(/\s+/g, '');

    if (!serieFolioNorm.startsWith('LMM')) return null;

    const suffix = serieFolioNorm.substring(3);
    let prefixOrder = 8; 

    if (/^\d+$/.test(suffix)) prefixOrder = 1;
    else if (serieFolioNorm.startsWith('LMMCR')) prefixOrder = 2;
    else if (serieFolioNorm.startsWith('LMMVEMB')) prefixOrder = 3;
    else if (serieFolioNorm.startsWith('LMMSUS')) prefixOrder = 4;
    else if (serieFolioNorm.startsWith('LMMCAP')) prefixOrder = 5;
    else if (serieFolioNorm.startsWith('LMMAO')) prefixOrder = 6;
    else if (serieFolioNorm.startsWith('LMMAD')) prefixOrder = 7;

    const numericPart = serieFolioNorm.replace(/[^0-9]/g, '');
    const finalData = {
        _group: prefixOrder,
        _folioPuro: numericPart.padStart(10, '0'),
        _norm: serieFolioNorm,
        'Serie-Folio Clave': serieFolioNorm,
        'Fecha Facturacion (PKT)': data['Fecha Facturacion'] || '',
        'Nombre Cliente (PKT)': data['Nombre Cliente'] || '',
        'Flete': Number(data.Flete || 0),
        'Subtotal Embalaje': Number(data['Subtotal Embalaje'] || 0),
        'Multiservicios': Number(data.Multiservicios || 0),
        'IVA (PKT)': Number(data['IVA (PKT)'] || 0),
        'Total (PKT)': Number(data['Total (PKT)'] || 0),
        'DIFERENCIA vs ABONO CONTPAQI': 0,
        'Fecha (CONT)': data.Fecha || '',
        'Folio Poliza': data.Folio_Poliza || '',
        'Codigo Cuenta': data.Codigo_Cuenta || '',
        'Nombre Cuenta': (data.Nombre_Cuenta || '').trim(),
        'Codigo Segmento': data.Codigo_Segmento || '',
        'Nombre Segmento': data.Nombre_Segmento || '',
        'Referencia (CONT)': data.Referencia || '',
        'Cargos (CONT)': (data.Tipo_Movimiento === 'Cargo') ? Number(data.Importe_Local || 0) : 0,
        'Abonos (CONT)': (data.Tipo_Movimiento === 'Abono') ? Number(data.Importe_Local || 0) : 0,
        'DIFERENCIA vs SUBTOTAL SAT': 0,
        'DIFERENCIA IVA': 0,
        'Fecha Expedicion (SAT)': data['Fecha expedición'] || '',
        'Total (SAT)': data.Total || 0,
        'Subtotal (SAT)': Number(data.Subtotal || 0),
        'Neto (SAT)': data.Neto || 0,
        'Traslado IVA (SAT)': Number(data['Traslado IVA'] || 0),
        'Total Descuento (SAT)': data['Total descuento'] || 0
    };

    if (finalData['Nombre Cuenta'] !== "Embalaje") {
        const subtotalOpPkt = finalData.Flete + finalData['Subtotal Embalaje'] + finalData.Multiservicios;
        finalData['DIFERENCIA vs ABONO CONTPAQI'] = subtotalOpPkt - (abonosPorFolio[serieFolioNorm] || 0);
        finalData['DIFERENCIA vs SUBTOTAL SAT'] = subtotalOpPkt - finalData['Subtotal (SAT)'];
        finalData['DIFERENCIA IVA'] = finalData['IVA (PKT)'] - finalData['Traslado IVA (SAT)'];
    }
    return { json: finalData };
}).filter(it => it !== null);

todosTransformados.sort((a, b) => a.json._norm.localeCompare(b.json._norm));

// 3. EXTRACCIÓN PRIMARIA DE CANCELACIONES
const residualItems = [];
const cancelledItems = [];

for (let i = 0; i < todosTransformados.length; i++) {
    const f1 = todosTransformados[i].json;
    const f2 = todosTransformados[i + 1] ? todosTransformados[i + 1].json : null;
    const f3 = todosTransformados[i + 2] ? todosTransformados[i + 2].json : null;

    if (f2 && f3 && f1._norm === f2._norm && f1._norm === f3._norm) {
        f1['Fecha Facturacion (PKT)'] = f3['Fecha Facturacion (PKT)'];
        f1['Nombre Cliente (PKT)'] = f3['Nombre Cliente (PKT)'];
        f1['Flete'] = f3['Flete']; f1['Subtotal Embalaje'] = f3['Subtotal Embalaje'];
        f1['Multiservicios'] = f3['Multiservicios']; f1['IVA (PKT)'] = f3['IVA (PKT)'];
        f1['Total (PKT)'] = f3['Total (PKT)'];
        f1['DIFERENCIA vs ABONO CONTPAQI'] = f3['DIFERENCIA vs ABONO CONTPAQI'];
        f1['DIFERENCIA vs SUBTOTAL SAT'] = f3['DIFERENCIA vs SUBTOTAL SAT'];
        f1['DIFERENCIA IVA'] = f3['DIFERENCIA IVA'];
        cancelledItems.push({ json: f1 }, { json: f2 });
        i += 2;
    } else {
        residualItems.push({ json: f1 });
    }
}

// 4. CLASIFICACIÓN FINAL DE DESPACHOS Y COMPLEMENTARIOS
const complementarios = {}; 
const listaLimpia = [];

residualItems.forEach(it => {
    const d = it.json;
    const suffix = d._norm.substring(3);
    const isPktZero = (d['Flete'] === 0 && d['Subtotal Embalaje'] === 0 && d['Multiservicios'] === 0 && d['Total (PKT)'] === 0);
    const isSatZero = (d['Total (SAT)'] === 0 && d['Subtotal (SAT)'] === 0 && d['Traslado IVA (SAT)'] === 0);

    if (/^\d+$/.test(suffix) && d['Total (PKT)'] === 0) d._group = 7;

    if (d['Cargos (CONT)'] > 0 && isPktZero && isSatZero) {
        const key = `${d['Folio Poliza']}|${d['Cargos (CONT)']}`;
        if (!complementarios[key]) complementarios[key] = [];
        complementarios[key].push({ json: d });
    } else {
        listaLimpia.push({ json: d });
    }
});

listaLimpia.sort((a, b) => {
    if (a.json._group !== b.json._group) return a.json._group - b.json._group;
    return a.json._folioPuro.localeCompare(b.json._folioPuro);
});

// 5. CONSTRUCCIÓN DE SALIDA FINAL
const outputItems = [];
const addSeparator = (text) => outputItems.push({ json: { 'Serie-Folio Clave': text } });
const addEmptyRows = () => outputItems.push({ json: {} }, { json: {} });

for (let g = 1; g <= 7; g++) {
    const itemsGrupo = listaLimpia.filter(it => it.json._group === g);

    if (itemsGrupo.length > 0) {
        if (g === 3) addSeparator("CFDIDEEMBALAJES");
        if (g === 4) addSeparator("CFDIDESUSTITUCIONES");
        if (g === 5) addSeparator("CFDIDEACCESSPOINT");
        if (g === 6) addSeparator("CFDIDEANTICIPOS");
        if (g === 7) addSeparator("CFDIDEDESPACHOSDEANTICIPOS");

        itemsGrupo.forEach(it => {
            const d = it.json;
            const currentGroup = d._group;
            const abonoCont = d['Abonos (CONT)'];
            const poliza = d['Folio Poliza'];

            delete d._group; delete d._folioPuro; delete d._norm;
            outputItems.push({ json: d });

            if (currentGroup === 4) {
                const key = `${poliza}|${abonoCont}`;
                if (complementarios[key]) {
                    complementarios[key].forEach(comp => {
                        const c = comp.json;
