const inputItem = items[0];

// 1. Manejo de error si el array está vacío o no tiene la columna de fecha
if (!inputItem || !inputItem.json || !inputItem.json['Fecha Facturacion (PKT)']) {
    // Devuelve valores por defecto para evitar errores en el título del Spreadsheet
    return [
        {
            json: {
                nombre_mes: 'Desconocido',
                año_completo: 'AAAA'
            }
        }
    ];
}

const dateString = inputItem.json['Fecha Facturacion (PKT)'];

// La fecha viene en formato YYYY-MM-DD, lo cual es seguro para construir el objeto Date.
const date = new Date(dateString);

// Configuramos los formateadores para el idioma español (México)
const monthFormatter = new Intl.DateTimeFormat('es-MX', { month: 'long' });
const yearFormatter = new Intl.DateTimeFormat('es-MX', { year: 'numeric' });

const monthName = monthFormatter.format(date);
const year = yearFormatter.format(date);

// 2. Capitalizar el nombre del mes (ej. "enero" -> "Enero")
const capitalizedMonth = monthName.charAt(0).toUpperCase() + monthName.slice(1);

// 3. Devolver un solo ítem con los valores para ser utilizados en el título
return [
    {
        json: {
            nombre_mes: capitalizedMonth,
            año_completo: year
        }
    }
];

const CREATION_NODE = "crear spreadsheet"; 
const DATA_NODE = "LMM"; 

const output = [];

try {
    const outputData = $items(CREATION_NODE)[0].json;
    const spreadsheetId = outputData.spreadsheetId;
    // Se mantiene su lógica de obtención de sheetId
    const sheetId = outputData.sheets ? outputData.sheets[0].properties.sheetId : outputData.spreadsheetId; 

    const datosFinales = $items(DATA_NODE);

    // 1. DEFINICIÓN DE COLORES
    const colorHeader = { red: 0, green: 0.125, blue: 0.375 }; // Azul Petróleo
    const colorRosaPastel = { red: 0.988, green: 0.894, blue: 0.839 }; // Rosa Pastel
    const colorAzulMedio = { red: 0.204, green: 0.596, blue: 0.859 }; // Azul Medio solicitado
    const colorErrorRojo = { red: 0.973, green: 0.412, blue: 0.420 }; // Rojo
    const colorNegro = { red: 0, green: 0, blue: 0 }; 
    const colorBlanco = { red: 1, green: 1, blue: 1 };

    const requests = [];

    // 2. ENCABEZADOS (Fila 0)
    requests.push({
        repeat_cell: {
            range: { sheetId: sheetId, startRowIndex: 0, endRowIndex: 1 },
            cell: {
                userEnteredFormat: {
                    backgroundColor: colorHeader,
                    textFormat: { bold: true, foregroundColor: colorBlanco },
                    horizontalAlignment: 'CENTER'
                }
            },
            fields: "userEnteredFormat(backgroundColor,textFormat,horizontalAlignment)"
        }
    });

    [8, 18, 19].forEach(colIndex => {
        requests.push({
            update_cells: {
                rows: [{ values: [{ userEnteredFormat: {
                    backgroundColor: colorRosaPastel,
                    textFormat: { bold: true, foregroundColor: colorHeader },
                    horizontalAlignment: 'CENTER'
                } }] }],
                range: { sheetId: sheetId, startRowIndex: 0, endRowIndex: 1, startColumnIndex: colIndex, endColumnIndex: colIndex + 1 },
                fields: "userEnteredFormat(backgroundColor,textFormat,horizontalAlignment)"
            }
        });
    });

    // 3. PROCESAMIENTO FILA POR FILA
    datosFinales.forEach((item, index) => {
        const rowIndex = index + 2; 
        const clave = (item.json['Serie-Folio Clave'] || '').toString().trim();

        if (clave === "") return; 

        if (clave.startsWith('CFDI')) {
            requests.push({
                repeat_cell: {
                    range: { sheetId: sheetId, startRowIndex: rowIndex, endRowIndex: rowIndex + 1 },
                    cell: {
                        userEnteredFormat: { 
                            backgroundColor: colorNegro,
                            textFormat: { foregroundColor: colorBlanco, bold: true }
                        }
                    },
                    fields: "userEnteredFormat(backgroundColor,textFormat)"
                }
            });
            return; 
        }

        const nombreCuenta = (item.json['Nombre Cuenta'] || '').trim();
        const diffA = Math.abs(item.json['DIFERENCIA vs ABONO CONTPAQI'] || 0);
        const diffB = Math.abs(item.json['DIFERENCIA vs SUBTOTAL SAT'] || 0);
        const diffC = Math.abs(item.json['DIFERENCIA IVA'] || 0);
        const tieneError = (diffA > 0.01 || diffB > 0.01 || diffC > 0.01);

        // LÓGICA MODIFICADA: Embalaje (Azul Medio en fila actual y anterior)
        if (nombreCuenta === "Embalaje") {
            requests.push({
                repeat_cell: {
                    range: { 
                        sheetId: sheetId, 
                        startRowIndex: rowIndex - 1, 
                        endRowIndex: rowIndex + 1 
                    },
                    cell: { userEnteredFormat: { backgroundColor: colorAzulMedio } },
                    fields: "userEnteredFormat(backgroundColor)"
                }
            });
        } 
        else if (tieneError) {
            requests.push({
                repeat_cell: {
                    range: { sheetId: sheetId, startRowIndex: rowIndex, endRowIndex: rowIndex + 1 },
                    cell: { userEnteredFormat: { backgroundColor: colorErrorRojo } },
                    fields: "userEnteredFormat(backgroundColor)"
                }
            });
        } 
        else {
            [8, 18, 19].forEach(colIdx => {
                requests.push({
                    update_cells: {
                        rows: [{ values: [{ userEnteredFormat: { backgroundColor: colorRosaPastel } }] }],
                        range: { sheetId: sheetId, startRowIndex: rowIndex, endRowIndex: rowIndex + 1, startColumnIndex: colIdx, endColumnIndex: colIdx + 1 },
                        fields: "userEnteredFormat(backgroundColor)"
                    }
                });
            });
        }
    });

    // 4. AUTO-AJUSTE
    requests.push({
        auto_resize_dimensions: {
            dimensions: { sheetId: sheetId, dimension: 'COLUMNS', startIndex: 0, endIndex: 26 }
        }
    });

    output.push({
        json: {
            spreadsheet_id: spreadsheetId,
            json_formato_raw: JSON.stringify({ requests })
        }
    });

} catch (error) {
    output.push({ json: { error: `ERROR EN DISEÑO LMM: ${error.message}` } });
}

return output;

