    // NOTA: El sheetId se obtiene de la respuesta del HTTP Request 'addSheet'.
    const sheetId = $items(NODO_HTTP_AGREGAR_HOJA)[0].json.replies[0].addSheet.properties.sheetId;
    // El spreadsheetId se obtiene del nodo que creó el documento maestro.
    const spreadsheetId = $items(NODO_ID_SPREADSHEET)[0].json.spreadsheetId;

    // 2. Definición de los 26 Encabezados Finales
    const headers = [
        "Serie-Folio Clave",
        "Fecha Facturacion (PKT)",
        "Nombre Cliente (PKT)",
        "Flete",
        "Subtotal Embalaje",
        "Multiservicios",
        "IVA (PKT)",
        "Total (PKT)",
        "DIFERENCIA vs ABONO CONTPAQI",
        "Fecha (CONT)",
        "Folio Poliza",
        "Codigo Cuenta",
        "Nombre Cuenta",
        "Codigo Segmento",
        "Nombre Segmento",
        "Referencia (CONT)",
        "Cargos (CONT)",
        "Abonos (CONT)",
        "DIFERENCIA vs SUBTOTAL SAT",
        "DIFERENCIA IVA",
        "Fecha Expedicion (SAT)",
        "Total (SAT)",
        "Subtotal (SAT)",
        "Neto (SAT)",
        "Traslado IVA (SAT)",
        "Total Descuento (SAT)"
    ];

    // 3. Generar el array de valores en el formato JSON de Google Sheets
    const headerValues = headers.map(header => {
        return { userEnteredValue: { stringValue: header } };
    });


    // 4. CONSTRUIR el JSON Body COMPLETO (Estructura para la petición batchUpdate)
    const jsonBody = {
        requests: [
            {
                updateCells: {
                    range: {
                        sheetId: sheetId, 
                        startRowIndex: 0,
                        endRowIndex: 1
                    },
                    rows: [
                        { values: headerValues }
                    ],
                    // Solo actualizamos el valor ingresado por el usuario (el texto del encabezado)
                    fields: "userEnteredValue" 
                }
            }
        ]
    };

    // 5. Devolver el Spreadsheet ID y el JSON Body como un string
    output.push({
        json: {
            spreadsheet_id: spreadsheetId,
            json_body_headers_raw: JSON.stringify(jsonBody) 
        }
    });

} catch (error) {
    console.error("Fallo al construir el JSON de columnas:", error);
    output.push({ json: { error: `FALLO DE ESTRUCTURA: ${error.message}. Verifique que los nodos existan y contengan los IDs.` } });
}

return output;

