const DATA_NODE = "CUU"; 
const ADD_SHEET_NODE = "HTTP_Agregar_Hoja2"; 

const output = [];

try {
    const spreadsheetId = $items(CREATION_NODE)[0].json.spreadsheetId;
    const sheetId = $items(ADD_SHEET_NODE)[0].json.replies[0].addSheet.properties.sheetId; 

    const datosFinales = $items(DATA_NODE);

    // 1. DEFINICIÓN DE COLORES
    const colorHeader = { red: 0, green: 0.125, blue: 0.375 }; 
    const colorRosaPastel = { red: 0.988, green: 0.894, blue: 0.839 }; 
    const colorAzulMedio = { red: 0.204, green: 0.596, blue: 0.859 }; // Azul Medio solicitado
    const colorErrorRojo = { red: 0.973, green: 0.412, blue: 0.420 }; 
    const colorNegro = { red: 0, green: 0, blue: 0 }; 
    const colorBlanco = { red: 1, green: 1, blue: 1 };

    const requests = [];

    // 2. FORMATO DE ENCABEZADOS (Fila 0)
    requests.push({
        repeat_cell: {
            range: { sheetId: sheetId, startRowIndex: 0, endRowIndex: 1 },
            cell: {
                userEnteredFormat: {
                    backgroundColor: colorHeader,
                    textFormat: { bold: true, foregroundColor: colorBlanco },
                    horizontalAlignment: 'CENTER'
                }
            },
            fields: "userEnteredFormat(backgroundColor,textFormat,horizontalAlignment)"
        }
    });

    [8, 18, 19].forEach(colIndex => {
        requests.push({
            update_cells: {
                rows: [{ values: [{ userEnteredFormat: {
                    backgroundColor: colorRosaPastel,
                    textFormat: { bold: true, foregroundColor: colorHeader },
                    horizontalAlignment: 'CENTER'
                } }] }],
                range: { sheetId: sheetId, startRowIndex: 0, endRowIndex: 1, startColumnIndex: colIndex, endColumnIndex: colIndex + 1 },
                fields: "userEnteredFormat(backgroundColor,textFormat,horizontalAlignment)"
            }
        });
    });

    // 3. PROCESAMIENTO DE DATOS
    datosFinales.forEach((item, index) => {
        const rowIndex = index + 2; 
        const clave = (item.json['Serie-Folio Clave'] || '').toString().trim();

        if (clave === "") return;

        // SEPARADORES NEGROS
        if (clave.startsWith('CFDI')) {
            requests.push({
                repeat_cell: {
                    range: { sheetId: sheetId, startRowIndex: rowIndex, endRowIndex: rowIndex + 1 },
                    cell: { 
                        userEnteredFormat: { 
                            backgroundColor: colorNegro,
                            textFormat: { foregroundColor: colorBlanco, bold: true }
                        } 
                    },
                    fields: "userEnteredFormat(backgroundColor,textFormat)"
                }
            });
            return;
        }

        const nombreCuenta = (item.json['Nombre Cuenta'] || '').trim();
        const diffA = Math.abs(item.json['DIFERENCIA vs ABONO CONTPAQI'] || 0);
        const diffB = Math.abs(item.json['DIFERENCIA vs SUBTOTAL SAT'] || 0);
        const diffC = Math.abs(item.json['DIFERENCIA IVA'] || 0);
        const tieneError = (diffA > 0.01 || diffB > 0.01 || diffC > 0.01);

        // REGLA MODIFICADA: Embalaje (Pintar fila actual y anterior en Azul Medio)
        if (nombreCuenta === "Embalaje") {
            requests.push({
                repeat_cell: {
                    range: { 
                        sheetId: sheetId, 
                        startRowIndex: rowIndex - 1, // Fila anterior
                        endRowIndex: rowIndex + 1    // Fila actual (el final es exclusivo)
                    },
                    cell: { userEnteredFormat: { backgroundColor: colorAzulMedio } },
                    fields: "userEnteredFormat(backgroundColor)"
                }
            });
        } 
        else if (tieneError) {
            requests.push({
                repeat_cell: {
                    range: { sheetId: sheetId, startRowIndex: rowIndex, endRowIndex: rowIndex + 1 },
                    cell: { userEnteredFormat: { backgroundColor: colorErrorRojo } },
                    fields: "userEnteredFormat(backgroundColor)"
                }
            });
        } 
        else {
            [8, 18, 19].forEach(colIdx => {
                requests.push({
                    update_cells: {
                        rows: [{ values: [{ userEnteredFormat: { backgroundColor: colorRosaPastel } }] }],
                        range: { sheetId: sheetId, startRowIndex: rowIndex, endRowIndex: rowIndex + 1, startColumnIndex: colIdx, endColumnIndex: colIdx + 1 },
                        fields: "userEnteredFormat(backgroundColor)"
                    }
                });
            });
        }
    });

    // 4. AUTO-AJUSTE
    requests.push({
        auto_resize_dimensions: {
            dimensions: { sheetId: sheetId, dimension: 'COLUMNS', startIndex: 0, endIndex: 26 }
        }
    });

    output.push({
        json: {
            spreadsheet_id: spreadsheetId,
            json_formato_raw: JSON.stringify({ requests })
        }
    });

} catch (error) {
    output.push({ json: { error: `ERROR EN DISEÑO CUL: ${error.message}` } });
}

return output;

