// ⚠️ AJUSTE NECESARIO: Nombres de los nodos
// ==============================================================================================================
const NODO_DESCARGA_HTTP = "HTTP Request";
const NODO_FECHA = "Obtener mes y año";
// ==============================================================================================================

const output = [];

try {
    // 1. Obtener la información binaria del nodo de descarga
    const binaryData = $items(NODO_DESCARGA_HTTP)[0].binary;

    // 2. Obtener las variables de nombre del nodo de fecha
    const fechaData = $items(NODO_FECHA)[0].json;
    const nombreMes = fechaData.nombre_mes;
    const añoCompleto = fechaData.año_completo;

    // 3. Crear el nuevo nombre de archivo
    // Estructura: "Cotejo Mes Año.xlsx"
    const nuevoNombreArchivo = `Cotejo ${nombreMes} ${añoCompleto}.xlsx`;

    // 4. Copiar y modificar el objeto binario
    for (const key in binaryData) {
        if (binaryData.hasOwnProperty(key)) {
            const fileItem = binaryData[key];

            // Creamos un nuevo objeto binario con el nombre modificado
            const newBinaryItem = {
                ...fileItem,
                fileName: nuevoNombreArchivo
            };

            // La salida del Code Node es un array que contiene un ítem con la propiedad 'binary'
            // Esto asegura que el archivo binario se transfiera correctamente al nodo de correo.
            output.push({
                json: {
                    // Puedes devolver el nombre para verificación
                    file_name_final: nuevoNombreArchivo
                },
                binary: {
                    [key]: newBinaryItem
                }
            });
            break; // Solo necesitamos procesar el primer archivo binario
        }
    }

    if (output.length === 0) {
        throw new Error("No se encontró archivo binario en el nodo de descarga.");
    }

} catch (error) {
    console.error("Fallo al renombrar el archivo binario:", error);
    output.push({ json: { error: `FALLO DE RENOMBRADO: ${error.message}` } });
}

return output;

