// ⚠️ Constante: Nombre de la columna que contiene la fecha en el archivo del SAT.
const NOMBRE_COLUMNA_FECHA = "Fecha expedición"; 
// ==============================================================================================================

const inputItem = items[0];
const output = [];

try {
    if (!inputItem || !inputItem.json || !inputItem.json[NOMBRE_COLUMNA_FECHA]) {
        throw new Error(`Fallo: La columna "${NOMBRE_COLUMNA_FECHA}" no fue encontrada o está vacía.`);
    }

    const rawDateValue = inputItem.json[NOMBRE_COLUMNA_FECHA];
    let date;

    // --- Lógica de Manejo de Formato ---
    if (typeof rawDateValue === 'number' && !isNaN(rawDateValue)) {
        // El valor es un NÚMERO SERIAL DE EXCEL (ej: 45293). Usamos la conversión compleja.

        const excelToJSDate = (serial) => {
            // Conversión de días desde 1/1/1900 a milisegundos desde 1/1/1970
            const utc_days  = serial - 25569;
            const date_info = new Date(utc_days * 86400 * 1000); 
            // Ajuste de zona horaria
            return new Date(date_info.getTime() + date_info.getTimezoneOffset() * 60000);
        };
        date = excelToJSDate(rawDateValue);

    } else if (typeof rawDateValue === 'string' && rawDateValue.match(/^\d{4}-\d{2}-\d{2}/)) {
        // El valor es una CADENA ISO válida (ej: "2024-01-02"). Lo usamos directamente.
        date = new Date(rawDateValue);

    } else {
        // El valor no es un número ni una cadena de fecha ISO válida.
        throw new Error(`Valor de fecha no compatible: "${rawDateValue}". Se esperaba un número serial o formato YYYY-MM-DD.`);
    }
    // --- Fin Lógica de Manejo de Formato ---


    // 3. Validar que la fecha sea correcta
    if (isNaN(date.getTime())) {
        throw new Error(`Fecha inválida generada a partir de "${rawDateValue}".`);
    }

    // 4. Calcular el Primer Día del Mes (fechaInicio)
    const year = date.getFullYear();
    const month = date.getMonth(); 
    const fechaInicioDate = new Date(year, month, 1);

    // 5. Calcular el Último Día del Mes (fechaFin)
    const fechaFinDate = new Date(year, month + 1, 0);

    // 6. Formatear las fechas a YYYY-MM-DD (Formato SQL)
    const toSQLDate = (d) => {
        const month = (d.getMonth() + 1).toString().padStart(2, '0'); 
        const day = d.getDate().toString().padStart(2, '0');
        return `${d.getFullYear()}-${month}-${day}`;
    };

    const fechaInicioSQL = toSQLDate(fechaInicioDate);
    const fechaFinSQL = toSQLDate(fechaFinDate);

    // 7. Preparar variables para la salida
    const monthName = new Intl.DateTimeFormat('es-MX', { month: 'long' }).format(date);
    const capitalizedMonth = monthName.charAt(0).toUpperCase() + monthName.slice(1);

    output.push({
        json: {
            fechaInicio: fechaInicioSQL, 
            fechaFin: fechaFinSQL,       
            nombre_mes: capitalizedMonth,
            año_completo: year.toString()
        }
    });

} catch (error) {
    console.error("Fallo en Code Node de Fecha:", error);
    throw new Error(`Error en el cálculo de fechas: ${error.message}`);
}

return output;

