        const tieneError = (diffA > 0.01 || diffB > 0.01 || diffC > 0.01);

        // REGLA MODIFICADA: Embalaje (Pintar fila actual y anterior en Azul Medio)
        if (nombreCuenta === "Embalaje") {
            requests.push({
                repeat_cell: {
                    range: { 
                        sheetId: sheetId, 
                        startRowIndex: rowIndex - 1, // Fila anterior
                        endRowIndex: rowIndex + 1    // Fila actual (el final es exclusivo)
                    },
                    cell: { userEnteredFormat: { backgroundColor: colorAzulMedio } },
                    fields: "userEnteredFormat(backgroundColor)"
                }
            });
        } 
        else if (tieneError) {
            requests.push({
                repeat_cell: {
                    range: { sheetId: sheetId, startRowIndex: rowIndex, endRowIndex: rowIndex + 1 },
                    cell: { userEnteredFormat: { backgroundColor: colorErrorRojo } },
                    fields: "userEnteredFormat(backgroundColor)"
                }
            });
        } 
        else {
            [8, 18, 19].forEach(colIdx => {
                requests.push({
                    update_cells: {
                        rows: [{ values: [{ userEnteredFormat: { backgroundColor: colorRosaPastel } }] }],
                        range: { sheetId: sheetId, startRowIndex: rowIndex, endRowIndex: rowIndex + 1, startColumnIndex: colIdx, endColumnIndex: colIdx + 1 },
                        fields: "userEnteredFormat(backgroundColor)"
                    }
                });
            });
        }
    });

    // 4. AUTO-AJUSTE
    requests.push({
        auto_resize_dimensions: {
            dimensions: { sheetId: sheetId, dimension: 'COLUMNS', startIndex: 0, endIndex: 26 }
        }
    });

    output.push({
        json: {
            spreadsheet_id: spreadsheetId,
            json_formato_raw: JSON.stringify({ requests })
        }
    });

} catch (error) {
    output.push({ json: { error: `ERROR EN DISEÑO CUL: ${error.message}` } });
}

return output;

// 1. MAPA DE ABONOS TOTALES (Normalizado)
const abonosPorFolio = {};
items.forEach(item => {
    const d = item.json;
    // Normalización: eliminamos cualquier espacio intermedio para el mapeo
    const folioRaw = (d['Serie-Folio'] || d.Referencia || '').toUpperCase();
    const folioNorm = folioRaw.replace(/\s+/g, '').trim(); 

    const abono = (d.Tipo_Movimiento === 'Abono' && Number(d.Importe_Local) > 0) ? Number(d.Importe_Local) : 0;
    if (!abonosPorFolio[folioNorm]) abonosPorFolio[folioNorm] = 0;
    abonosPorFolio[folioNorm] += abono;
});

// 2. TRANSFORMACIÓN INICIAL (Filtro CLMM - 4 caracteres con Normalización)
const todosTransformados = items.map(item => {
    const data = item.json;
    const serieFolioOriginal = (data['Serie-Folio'] || data.Referencia || '').trim().toUpperCase();

    // Normalización para comparaciones: "CLMM 123" -> "CLMM123"
    const serieFolioNorm = serieFolioOriginal.replace(/\s+/g, '');

    if (!serieFolioNorm.startsWith('CLMM')) return null;

    const suffix = serieFolioNorm.substring(4);
    let prefixOrder = 8; 

    if (/^\d+$/.test(suffix)) prefixOrder = 1;
    else if (serieFolioNorm.startsWith('CLMMCR')) prefixOrder = 2;
    else if (serieFolioNorm.startsWith('CLMMVEMB')) prefixOrder = 3;
    else if (serieFolioNorm.startsWith('CLMMSUS')) prefixOrder = 4;
    else if (serieFolioNorm.startsWith('CLMMCAP')) prefixOrder = 5;
    else if (serieFolioNorm.startsWith('CLMMAO')) prefixOrder = 6;
    else if (serieFolioNorm.startsWith('CLMMAD')) prefixOrder = 7;

    const numericPart = serieFolioNorm.replace(/[^0-9]/g, '');
    const finalData = {
        _group: prefixOrder,
        _folioPuro: numericPart.padStart(10, '0'),
        _norm: serieFolioNorm, // Campo auxiliar para detectar tripletes sin espacios
        'Serie-Folio Clave': serieFolioNorm, 
        'Fecha Facturacion (PKT)': data['Fecha Facturacion'] || '',
        'Nombre Cliente (PKT)': data['Nombre Cliente'] || '',
        'Flete': Number(data.Flete || 0),
        'Subtotal Embalaje': Number(data['Subtotal Embalaje'] || 0),
        'Multiservicios': Number(data.Multiservicios || 0),
        'IVA (PKT)': Number(data['IVA (PKT)'] || 0),
        'Total (PKT)': Number(data['Total (PKT)'] || 0),
        'DIFERENCIA vs ABONO CONTPAQI': 0,
        'Fecha (CONT)': data.Fecha || '',
        'Folio Poliza': data.Folio_Poliza || '',
        'Codigo Cuenta': data.Codigo_Cuenta || '',
        'Nombre Cuenta': (data.Nombre_Cuenta || '').trim(),
        'Codigo Segmento': data.Codigo_Segmento || '',
        'Nombre Segmento': data.Nombre_Segmento || '',
        'Referencia (CONT)': data.Referencia || '',
        'Cargos (CONT)': (data.Tipo_Movimiento === 'Cargo') ? Number(data.Importe_Local || 0) : 0,
        'Abonos (CONT)': (data.Tipo_Movimiento === 'Abono') ? Number(data.Importe_Local || 0) : 0,
        'DIFERENCIA vs SUBTOTAL SAT': 0,
        'DIFERENCIA IVA': 0,
        'Fecha Expedicion (SAT)': data['Fecha expedición'] || '',
        'Total (SAT)': data.Total || 0,
        'Subtotal (SAT)': Number(data.Subtotal || 0),
        'Neto (SAT)': data.Neto || 0,
        'Traslado IVA (SAT)': Number(data['Traslado IVA'] || 0),
        'Total Descuento (SAT)': data['Total descuento'] || 0
    };

    if (finalData['Nombre Cuenta'] !== "Embalaje") {
        const subtotalOpPkt = finalData.Flete + finalData['Subtotal Embalaje'] + finalData.Multiservicios;
        finalData['DIFERENCIA vs ABONO CONTPAQI'] = subtotalOpPkt - (abonosPorFolio[serieFolioNorm] || 0);
        finalData['DIFERENCIA vs SUBTOTAL SAT'] = subtotalOpPkt - finalData['Subtotal (SAT)'];
        finalData['DIFERENCIA IVA'] = finalData['IVA (PKT)'] - finalData['Traslado IVA (SAT)'];
    }
    return { json: finalData };
}).filter(it => it !== null);

// Ordenar por el normalizado para asegurar que tripletes queden juntos
todosTransformados.sort((a, b) => a.json._norm.localeCompare(b.json._norm));

// 3. EXTRACCIÓN PRIMARIA DE CANCELACIONES (Basado en _norm)
const residualItems = [];
const cancelledItems = [];

for (let i = 0; i < todosTransformados.length; i++) {
    const f1 = todosTransformados[i].json;
    const f2 = todosTransformados[i + 1] ? todosTransformados[i + 1].json : null;
    const f3 = todosTransformados[i + 2] ? todosTransformados[i + 2].json : null;

    if (f2 && f3 && f1._norm === f2._norm && f1._norm === f3._norm) {
        // Fusión: Se toman datos de f3 y se inyectan en f1
        f1['Fecha Facturacion (PKT)'] = f3['Fecha Facturacion (PKT)'];
        f1['Nombre Cliente (PKT)'] = f3['Nombre Cliente (PKT)'];
        f1['Flete'] = f3['Flete']; f1['Subtotal Embalaje'] = f3['Subtotal Embalaje'];
        f1['Multiservicios'] = f3['Multiservicios']; f1['IVA (PKT)'] = f3['IVA (PKT)'];
        f1['Total (PKT)'] = f3['Total (PKT)'];
        f1['DIFERENCIA vs ABONO CONTPAQI'] = f3['DIFERENCIA vs ABONO CONTPAQI'];
        f1['DIFERENCIA vs SUBTOTAL SAT'] = f3['DIFERENCIA vs SUBTOTAL SAT'];
        f1['DIFERENCIA IVA'] = f3['DIFERENCIA IVA'];
        cancelledItems.push({ json: f1 }, { json: f2 });
        i += 2; // f3 es el residuo y se borra
    } else {
        residualItems.push({ json: f1 });
    }
}

// 4. CLASIFICACIÓN FINAL (Grupo 7 y Complementarios)
const complementarios = {}; 
const listaLimpia = [];

residualItems.forEach(it => {
    const d = it.json;
    const suffix = d._norm.substring(4);
    const isPktZero = (d['Flete'] === 0 && d['Subtotal Embalaje'] === 0 && d['Multiservicios'] === 0 && d['Total (PKT)'] === 0);
    const isSatZero = (d['Total (SAT)'] === 0 && d['Subtotal (SAT)'] === 0 && d['Traslado IVA (SAT)'] === 0);

    if (/^\d+$/.test(suffix) && d['Total (PKT)'] === 0) d._group = 7;

    if (d['Cargos (CONT)'] > 0 && isPktZero && isSatZero) {
        const key = `${d['Folio Poliza']}|${d['Cargos (CONT)']}`;
        if (!complementarios[key]) complementarios[key] = [];
        complementarios[key].push({ json: d });
    } else {
        listaLimpia.push({ json: d });
    }
});

listaLimpia.sort((a, b) => {
    if (a.json._group !== b.json._group) return a.json._group - b.json._group;
    return a.json._folioPuro.localeCompare(b.json._folioPuro);
});

// 5. CONSTRUCCIÓN DE SALIDA FINAL
const outputItems = [];
const addSeparator = (text) => outputItems.push({ json: { 'Serie-Folio Clave': text } });
const addEmptyRows = () => outputItems.push({ json: {} }, { json: {} });

for (let g = 1; g <= 7; g++) {
    const itemsGrupo = listaLimpia.filter(it => it.json._group === g);

    if (itemsGrupo.length > 0) {
        if (g === 3) addSeparator("CFDIDEEMBALAJES");
        if (g === 4) addSeparator("CFDIDESUSTITUCIONES");
        if (g === 5) addSeparator("CFDIDEACCESSPOINT");
        if (g === 6) addSeparator("CFDIDEANTICIPOS");
        if (g === 7) addSeparator("CFDIDEDESPACHOSDEANTICIPOS");

        itemsGrupo.forEach(it => {
            const d = it.json;
            const currentGroup = d._group;
            const abonoCont = d['Abonos (CONT)'];
            const poliza = d['Folio Poliza'];

            delete d._group; delete d._folioPuro; delete d._norm;
            outputItems.push({ json: d });

            if (currentGroup === 4) {
                const key = `${poliza}|${abonoCont}`;
                if (complementarios[key]) {
                    complementarios[key].forEach(comp => {
                        const c = comp.json;
                        delete c._group; delete c._folioPuro; delete c._norm;
                        outputItems.push({ json: c });
                    });
                    delete complementarios[key];
                }
            }
        });
        addEmptyRows(); 
    }
}

const huerfanos = Object.values(complementarios).flat();
if (huerfanos.length > 0) {
    huerfanos.forEach(it => {
        const d = it.json;
        delete d._group; delete d._folioPuro; delete d._norm;
        outputItems.push({ json: d });
    });
    addEmptyRows(); 
}

if (cancelledItems.length > 0) {
    addSeparator("CFDICARGADOSENCONTABILIDAD(CANCELACIONES)");
    cancelledItems.forEach(it => {
        const d = it.json;
        delete d._group; delete d._folioPuro; delete d._norm;
        outputItems.push({ json: d });
    });
    addEmptyRows(); 
}

return outputItems;

const rows = items.map((item, index) => {
  const rowValues = Object.values(item.json);
  const strValues = rowValues.map(v => String(v || "").trim());

  // Identificar si la fila es un separador (totalmente vacía)
  const isSeparator = strValues.every(v => v === "");
  // Identificar el título principal (fila 0)
  const isMainTitle = index === 0;

  // Identificar encabezados por palabras clave
  const headerKeywords = ["Sucursal", "CUENTA", "VENTAS", "NOTAS_CRED", "EMBALAJE", "PKTONE", "CONTPAQ", "PKT_Ventas", "TOTAL"];
  const isHeader = strValues.some(v => headerKeywords.includes(v));

  return {
    values: strValues.map((strVal) => {
      // CORRECCIÓN COLOR: Solo rojo si EMPIEZA con "-" (montos negativos)
      // Esto evita que las cuentas (ej. 401-001...) se pinten de rojo
      const isNegativeAmount = strVal.startsWith("-");

      // CORRECCIÓN BORDES: Solo si NO es separador y NO es el título principal
      const hasBorder = !isSeparator && !isMainTitle;

      const cellFormat = {
        textFormat: {
          foregroundColor: isNegativeAmount ? { red: 0.8, green: 0, blue: 0 } : { red: 0, green: 0, blue: 0 },
          bold: isMainTitle || isHeader,
          fontSize: isMainTitle ? 14 : 10
        },
        backgroundColor: isHeader ? { red: 0.9, green: 0.9, blue: 0.9 } : { red: 1, green: 1, blue: 1 }
      };

      // Aplicar bordes solo a las tablas
      if (hasBorder) {
        cellFormat.borders = {
          top: { style: "SOLID" }, bottom: { style: "SOLID" },
          left: { style: "SOLID" }, right: { style: "SOLID" }
        };
      }

      return {
        userEnteredValue: { stringValue: strVal },
        userEnteredFormat: cellFormat
      };
    })
  };
});

return [{ json: { rowData: rows } }];

// ==============================================================================================================
// ⚠️ AJUSTE NECESARIO: Nombres de los nodos
// ==============================================================================================================
const NODO_DESCARGA_HTTP = "Descargar archivo";
const NODO_FECHA = "Obtener mes y año";
// ==============================================================================================================

const output = [];

try {
    // 1. Obtener la información binaria del nodo de descarga
    const binaryData = $items(NODO_DESCARGA_HTTP)[0].binary;

    // 2. Obtener las variables de nombre del nodo de fecha
    const fechaData = $items(NODO_FECHA)[0].json;
    const nombreMes = fechaData.nombre_mes;
    const añoCompleto = fechaData.año_completo;

    // 3. Crear el nuevo nombre de archivo
    // Estructura: "Cotejo Mes Año.xlsx"
    const nuevoNombreArchivo = `Diferencia ${nombreMes} ${añoCompleto}.xlsx`;

    // 4. Copiar y modificar el objeto binario
    for (const key in binaryData) {
        if (binaryData.hasOwnProperty(key)) {
            const fileItem = binaryData[key];

            // Creamos un nuevo objeto binario con el nombre modificado
            const newBinaryItem = {
                ...fileItem,
                fileName: nuevoNombreArchivo
            };

            // La salida del Code Node es un array que contiene un ítem con la propiedad 'binary'
            // Esto asegura que el archivo binario se transfiera correctamente al nodo de correo.
            output.push({
                json: {
                    // Puedes devolver el nombre para verificación
                    file_name_final: nuevoNombreArchivo
                },
                binary: {
                    [key]: newBinaryItem
                }
            });
            break; // Solo necesitamos procesar el primer archivo binario
        }
    }

    if (output.length === 0) {
        throw new Error("No se encontró archivo binario en el nodo de descarga.");
    }

} catch (error) {
    console.error("Fallo al renombrar el archivo binario:", error);
    output.push({ json: { error: `FALLO DE RENOMBRADO: ${error.message}` } });
}

return output;
